(function() {
  'use strict';

  // 等待 DOM 加载完成
  document.addEventListener('DOMContentLoaded', function() {
    const toggleBtns = document.querySelectorAll('.toggle-btn');
    const skillProductivity = document.getElementById('skill-productivity');
    const skillContext = document.getElementById('skill-context');
    const barQ1 = document.getElementById('bar-q1');
    const barQ5 = document.getElementById('bar-q5');
    const labelQ1 = document.getElementById('label-q1');
    const labelQ5 = document.getElementById('label-q5');

    // 数据来源
    const data = {
      'low-skill': {
        value: '35%',
        context: '最低技能五分位代理看到最显著的生产力提升。',
        source: 'S421',
        barHeight: 150,
        barY: 100,
        labelY: 90
      },
      'high-skill': {
        value: '≈0%',
        context: '最高技能五分位代理几乎没有生产力提升，甚至可能出现轻微负面影响。',
        source: 'S423',
        barHeight: 10,
        barY: 240,
        labelY: 230
      }
    };

    // 切换技能组显示
    toggleBtns.forEach(btn => {
      btn.addEventListener('click', function() {
        const group = this.dataset.group;

        // 更新按钮状态
        toggleBtns.forEach(b => {
          b.classList.remove('active');
          b.setAttribute('aria-pressed', 'false');
        });
        this.classList.add('active');
        this.setAttribute('aria-pressed', 'true');

        // 更新数据显示
        const selectedData = data[group];
        skillProductivity.textContent = selectedData.value;
        skillContext.textContent = selectedData.context;

        // 更新图表
        if (group === 'low-skill') {
          barQ1.setAttribute('height', selectedData.barHeight);
          barQ1.setAttribute('y', selectedData.barY);
          barQ5.setAttribute('height', data['high-skill'].barHeight);
          barQ5.setAttribute('y', data['high-skill'].barY);
          labelQ1.setAttribute('y', selectedData.labelY);
          labelQ5.setAttribute('y', data['high-skill'].labelY);

          barQ1.style.opacity = '1';
          barQ5.style.opacity = '0.3';
        } else {
          barQ5.setAttribute('height', selectedData.barHeight);
          barQ5.setAttribute('y', selectedData.barY);
          barQ1.setAttribute('height', data['low-skill'].barHeight);
          barQ1.setAttribute('y', data['low-skill'].barY);
          labelQ5.setAttribute('y', selectedData.labelY);
          labelQ1.setAttribute('y', data['low-skill'].labelY);

          barQ5.style.opacity = '1';
          barQ1.style.opacity = '0.3';
        }
      });
    });

    // 来源按钮处理
    document.querySelectorAll('.source-btn').forEach(btn => {
      btn.addEventListener('click', function() {
        // 来源处理由内核负责，此处仅保留接口
        const sourceId = this.dataset.source;
        // 实际行为由 paperMind 内核处理
      });
    });

    // 键盘导航支持
    document.querySelector('.toggle-group').addEventListener('keydown', function(e) {
      if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
        e.preventDefault();
        const current = document.querySelector('.toggle-btn.active');
        const buttons = Array.from(toggleBtns);
        const currentIndex = buttons.indexOf(current);

        let nextIndex;
        if (e.key === 'ArrowLeft') {
          nextIndex = currentIndex > 0 ? currentIndex - 1 : buttons.length - 1;
        } else {
          nextIndex = currentIndex < buttons.length - 1 ? currentIndex + 1 : 0;
        }

        buttons[nextIndex].click();
        buttons[nextIndex].focus();
      }
    });
  });
})();
